import{_ as l,o as e,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-06-15","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-06-15","date":"2021-06-15T00:00:00.000Z","updated":"2021-06-16T00:00:00.000Z","tags":["Ceph","Dashboard","RGW","Configuration Optimization","Rook"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-06-15.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-06-15.md","lastUpdated":1780459816000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-06-15.md"};function r(s,a,n,h,p,u){return e(),o("div",null,[...a[0]||(a[0]=[t('<p>会议纪要</p><h3 id="会议主题-ceph-dashboard-配置与-rgw-连接优化" tabindex="-1">会议主题：Ceph Dashboard 配置与 RGW 连接优化 <a class="header-anchor" href="#会议主题-ceph-dashboard-配置与-rgw-连接优化" aria-label="Permalink to &quot;会议主题：Ceph Dashboard 配置与 RGW 连接优化&quot;">​</a></h3><h3 id="参会人员-alfonso、sage、casey、jehuda-等" tabindex="-1">参会人员：Alfonso、Sage、Casey、Jehuda 等 <a class="header-anchor" href="#参会人员-alfonso、sage、casey、jehuda-等" aria-label="Permalink to &quot;参会人员：Alfonso、Sage、Casey、Jehuda 等&quot;">​</a></h3><h3 id="会议时间-2021年6月15日" tabindex="-1">会议时间：2021年6月15日 <a class="header-anchor" href="#会议时间-2021年6月15日" aria-label="Permalink to &quot;会议时间：2021年6月15日&quot;">​</a></h3><h3 id="会议地点-视频会议" tabindex="-1">会议地点：视频会议 <a class="header-anchor" href="#会议地点-视频会议" aria-label="Permalink to &quot;会议地点：视频会议&quot;">​</a></h3><h3 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h3><ol><li><strong>Ceph Dashboard 中 Selfie IDM 网络设置的 Pull Request</strong></li><li><strong>RGW 连接凭证的配置与优化</strong></li><li><strong>NFS 导出创建的 CLI 命令优化</strong></li><li><strong>Rook 管理模块的当前状态与后续行动</strong></li></ol><h3 id="讨论内容" tabindex="-1">讨论内容： <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容：&quot;">​</a></h3><ol><li><p><strong>Selfie IDM 网络设置</strong>：</p><ul><li>讨论了在 Dashboard 中设置 Selfie IDM 网络的 Pull Request。</li><li>确认等待 Sage 加入会议以进一步讨论。</li></ul></li><li><p><strong>RGW 连接凭证配置</strong>：</p><ul><li>讨论了当前凭证设置方式，即按网关设置。</li><li>提出按领域设置凭证的提案，以简化配置。</li><li>讨论了凭证设置的具体实现细节，包括用户升级过程。</li></ul></li><li><p><strong>NFS 导出创建的 CLI 命令优化</strong>：</p><ul><li>讨论了当前 CLI 命令的不足，特别是幂等性问题。</li><li>提出使用“apply”命令替代“create”和“update”，以简化操作并确保幂等性。</li></ul></li><li><p><strong>Rook 管理模块</strong>：</p><ul><li>更新了 Rook 管理模块的当前状态，包括 RGW 的 realm 和 zone 标志的启用情况。</li><li>讨论了 Rook 客户端 Python 库的维护和使用问题。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h3><ol><li><p><strong>RGW 连接凭证配置</strong>：</p><ul><li>决定采用按领域设置凭证的方式，简化配置。</li><li>确认需要考虑用户升级过程，确保凭证设置的平滑过渡。</li></ul></li><li><p><strong>NFS 导出创建的 CLI 命令优化</strong>：</p><ul><li>决定使用“apply”命令替代“create”和“update”，以简化操作并确保幂等性。</li></ul></li><li><p><strong>Rook 管理模块</strong>：</p><ul><li>确认 Rook 客户端 Python 库的维护和使用问题，需要进一步测试和验证。</li></ul></li></ol><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ol><li><p><strong>RGW 连接凭证配置</strong>：</p><ul><li>更新 Pull Request，确保凭证设置按领域进行。</li><li>准备用户升级指南，确保凭证设置的平滑过渡。</li></ul></li><li><p><strong>NFS 导出创建的 CLI 命令优化</strong>：</p><ul><li>更新 CLI 命令，使用“apply”替代“create”和“update”。</li><li>确保新命令的幂等性和正确性。</li></ul></li><li><p><strong>Rook 管理模块</strong>：</p><ul><li>进一步测试 Rook 客户端 Python 库，确保其稳定性和正确性。</li><li>准备 Rook 管理模块的后续开发计划。</li></ul></li></ol><h3 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h3><ul><li>确认无其他议题后，会议结束。</li><li>感谢所有参会人员，会议圆满结束。</li></ul>',15)])])}const g=l(i,[["render",r]]);export{c as __pageData,g as default};
